        demonstrateConnectedComponents(graph);
        demonstrateCycleDetection(graph);
        demonstratePathFinding(graph);

        System.out.println("\n╔═══════════════════════════════════════════════════════════╗");
        System.out.println("║          Testing with Disconnected Graph                 ║");
        System.out.println("╚═══════════════════════════════════════════════════════════╝\n");

        Graph disconnectedGraph = buildDisconnectedGraph();
        demonstrateConnectedComponents(disconnectedGraph);
    }

    private static void demonstrateTraversals(Graph graph) {
        System.out.println("─── TRAVERSAL ALGORITHMS ───\n");

        List<Integer> dfsRecursive = DepthFirstSearch.recursive().traverse(graph);
        System.out.println("DFS (Recursive): " + formatPath(dfsRecursive));

        List<Integer> dfsIterative = DepthFirstSearch.iterative().traverse(graph);
        System.out.println("DFS (Iterative): " + formatPath(dfsIterative));

        List<Integer> bfs = new BreadthFirstSearch().traverse(graph);
        System.out.println("BFS:             " + formatPath(bfs));

        System.out.println("\n─── GRAPH STATISTICS ───\n");
        System.out.println("Vertices: " + graph.getVertexCount());
        System.out.println("Edges:    " + graph.getEdgeCount());
        System.out.println("Vertex 0 degree: " + graph.getDegree(0));
        System.out.println("Vertices with degree 2: " + graph.getVerticesWithDegree(2));
    }

    private static void demonstrateConnectedComponents(Graph graph) {
        System.out.println("\n─── CONNECTED COMPONENTS ───\n");

        ConnectedComponentsAnalyzer analyzer = new ConnectedComponentsAnalyzer(graph);
        List<List<Integer>> components = analyzer.findConnectedComponents();

        System.out.println("Number of components: " + analyzer.getComponentCount());
        System.out.println("Is connected: " + analyzer.isConnected());

        for (int i = 0; i < components.size(); i++) {
            System.out.println("  Component " + i + ": " + components.get(i));
        }
    }

    private static void demonstrateCycleDetection(Graph graph) {
        System.out.println("\n─── CYCLE DETECTION ───\n");

        CycleDetector detector = new CycleDetector(graph);
        boolean hasCycle = detector.hasCycle();

        System.out.println("Has cycle: " + hasCycle);
        if (hasCycle) {
            System.out.println("Cycle vertices: " + detector.getCycleVertices());
        }
    }

    private static void demonstratePathFinding(Graph graph) {
        System.out.println("\n─── PATH FINDING ───\n");

        PathFinder pathFinder = new PathFinder(graph);

        int source = 0;
        int destination = 1;
        Optional<List<Integer>> path = pathFinder.findPath(source, destination);

        if (path.isPresent()) {
            System.out.println("Path from " + source + " to " + destination + ": " +
                    formatPath(path.get()));
            System.out.println("Distance: " + pathFinder.getDistance(source, destination));
        } else {
            System.out.println("No path exists from " + source + " to " + destination);
        }

        Optional<List<Integer>> path2 = pathFinder.findPath(0, 5);
        if (path2.isPresent()) {
            System.out.println("Path from 0 to 5: " + formatPath(path2.get()));
        } else {
            System.out.println("No path exists from 0 to 5");
        }
    }

    private static Graph buildSimpleGraph() {
        return new GraphBuilder(6)
                .addEdge(1, 2)
                .addEdge(0, 3)
                .addEdge(2, 0)
                .addEdge(5, 4)
                .build();
    }

    private static Graph buildDisconnectedGraph() {
        return new GraphBuilder(5)
                .addEdge(0, 1)
                .addEdge(1, 2)
                .addEdge(3, 4)
                .build();
    }

    private static String formatPath(List<Integer> path) {
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < path.size(); i++) {
            sb.append(path.get(i));
            if (i < path.size() - 1) {
                sb.append(" → ");
            }
        }
        return sb.toString();
    }
}

